def _check_single_file_task(task, fps: list, violations: list[str]) -> None:
    """Check that a task lists exactly 1 file."""
    if len(fps) != 1:
        violations.append(f"task {getattr(task, 'id', '?')} lists {len(fps)} files (exactly 1 required)")


def _check_file_collisions(fps: list, seen: set[str], violations: list[str]) -> None:
